details.codeblock:
package nautilus
import "vendor:dicom" import "vendor:skald"
Layout_Mode :: enum u8 { Single_1x1, Split_1x2, Grid_2x2 } Tool_Mode :: enum u8 { Window_Level, Pan, Zoom, Probe, Measure_Length, Measure_Angle }
Instance_Entry :: struct { file_path: string, instance_number: int, has_instance_num: bool, slice_location: f64, has_slice_loc: bool, rows, cols: int, frames: int, }
Series_Entry :: struct { series_uid: string, series_num: int, description: string, modality: string, instances: [dynamic]Instance_Entry, }
Study_Entry :: struct { study_uid: string, patient_name: string, patient_id: string, study_date: string, description: string, series: [dynamic]Series_Entry, }
Viewport_State :: struct { study_idx, series_idx: int, instance_idx: int, frame_idx: int, request_seq: u64, // 显示变换与窗位状态 center, width: f64, window_initialized: bool, invert: bool, zoom: f32, // 1.0 = fit to viewport pan: [2]f32, rotation_quadrants: int, // 0, 1, 2, 3 (×90°) flip_h, flip_v: bool, // 纹理上传同步版本号 uploaded_key: Frame_Key, uploaded_wl_gen: u64, uploaded_proxy: bool, // 测量标注 rulers: [dynamic]Ruler_Annotation, angles: [dynamic]Angle_Annotation, }
